"""Structured AI response schema, validation, and safety checking."""

import json
import logging
import re
from enum import Enum

from pydantic import BaseModel, Field, field_validator

from app.utils.text import contains_sensitive_secrets

logger = logging.getLogger(__name__)


class ActionType(str, Enum):
    REPLY = "reply"
    NEXT = "next"
    STOP = "stop"
    IGNORE = "ignore"
    SEND_AUTHORIZED_PHOTO = "send_authorized_photo"


class AIResponse(BaseModel):
    """Structured response model generated by LLM."""

    action: ActionType = Field(default=ActionType.REPLY, description="Requested action to perform")
    text: str | None = Field(default=None, description="Conversational text reply")
    photo_id: str | None = Field(default=None, description="Authorized photo alias (e.g. PHOTO_1)")
    confidence: float = Field(default=1.0, ge=0.0, le=1.0, description="Confidence score")
    reason: str | None = Field(default=None, description="Reason for stopping/nexting/ignoring")

    # Extra conversation intelligence extracted from context
    extracted_telegram_username: str | None = Field(
        default=None, description="Disclosed Telegram username"
    )
    detected_age: int | None = Field(default=None, description="Age stated by participant")
    detected_intent: str | None = Field(default=None, description="Inferred conversational intent")

    @field_validator("text")
    @classmethod
    def clean_text_field(cls, v: str | None) -> str | None:
        if v is None:
            return None
        v = v.strip()
        return v if v else None


class ResponseSafetyValidator:
    """Validates and sanitizes AI responses against leaks and policy violations."""

    def __init__(self, forbidden_secrets: list[str] | None = None) -> None:
        self.forbidden_secrets = [s for s in (forbidden_secrets or []) if s and len(s) > 4]

    def validate_and_clean(self, response: AIResponse) -> tuple[bool, str, AIResponse]:
        """
        Validate safety rules.
        Returns: (is_safe: bool, reason: str, cleaned_response: AIResponse)
        """
        # 1. Check if action requires text
        if response.action == ActionType.REPLY and not response.text:
            return False, "Action is reply but text is empty", response

        # 2. Check if action is photo but missing photo_id
        if response.action == ActionType.SEND_AUTHORIZED_PHOTO and not response.photo_id:
            return False, "Action is send_authorized_photo but photo_id is missing", response

        # 3. Secret leak detection in text
        if response.text:
            if contains_sensitive_secrets(response.text, self.forbidden_secrets):
                logger.error("SECURITY ALERT: AI response attempted to leak confidential secret!")
                return False, "Secret leak detected in response text", response

            # Check for suspicious system prompt leakage or code execution attempts
            leak_markers = [
                "SYSTEM PROMPT:",
                "RULES:",
                "DATABASE_URL",
                "TELEGRAM_API_ID",
                "TELEGRAM_API_HASH",
                "LLM_API_KEY",
                "import telethon",
                "os.system",
            ]
            for marker in leak_markers:
                if marker.lower() in response.text.lower():
                    logger.error(f"SECURITY ALERT: AI response contained leak marker: {marker}")
                    return False, f"Forbidden system marker in response: {marker}", response

            # Maximum sensible message length (e.g. 2000 chars)
            if len(response.text) > 2000:
                response.text = response.text[:2000]

        return True, "OK", response


def parse_ai_json_output(raw_output: str) -> AIResponse | None:
    """Parse JSON or JSON markdown block from LLM output into validated AIResponse."""
    if not raw_output:
        return None

    cleaned = raw_output.strip()

    # Extract json from markdown block ```json ... ``` if present
    json_match = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", cleaned, re.DOTALL)
    if json_match:
        cleaned = json_match.group(1)
    else:
        # Or locate first { and last }
        first_brace = cleaned.find("{")
        last_brace = cleaned.rfind("}")
        if first_brace != -1 and last_brace != -1 and last_brace > first_brace:
            cleaned = cleaned[first_brace : last_brace + 1]

    try:
        data = json.loads(cleaned)
        return AIResponse.model_validate(data)
    except Exception as e:
        logger.debug(f"LLM returned plain text instead of JSON schema ({e}). Treating output as direct reply.")
        # Fallback to direct reply if plain text was returned
        if raw_output and len(raw_output.strip()) > 0:
            return AIResponse(action=ActionType.REPLY, text=raw_output.strip())
        return None
